BEGIN READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,topic_id,created_at,subject,message_id,length(body) AS body_length,left(body,12000) AS body
 FROM messages
 WHERE subject ILIKE '%GIN%' AND body ILIKE '%consistent%'
 AND (body ILIKE '%cache%' OR body ILIKE '%memo%')
 AND (body ILIKE '%miss%' OR body ILIKE '%adapt%' OR body ILIKE '%consecutive%' OR body ILIKE '%hit rate%')
 ORDER BY created_at DESC,id DESC LIMIT 20
) q;
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,topic_id,created_at,subject,message_id,length(body) AS body_length,left(body,12000) AS body
 FROM messages WHERE body ILIKE '%ginlogic.c%' AND (body ILIKE '%cache%' OR body ILIKE '%memo%')
 ORDER BY created_at DESC,id DESC LIMIT 15
) q;
COMMIT;
